import{_ as e,o,c as n,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Contracts — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Contracts — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/contracts"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Contracts — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/contracts"}]]},"headers":[],"relativePath":"user-guide/contracts.md","filePath":"user-guide/contracts.md","lastUpdated":1787698014000}'),r={name:"user-guide/contracts.md"};function s(i,t,c,l,d,g){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="contracts-—-user-guide" tabindex="-1">Contracts — User Guide <a class="header-anchor" href="#contracts-—-user-guide" aria-label="Permalink to &quot;Contracts — User Guide&quot;">​</a></h1><h2 id="who-can-use-contracts" tabindex="-1">Who can use Contracts <a class="header-anchor" href="#who-can-use-contracts" aria-label="Permalink to &quot;Who can use Contracts&quot;">​</a></h2><p>Your workspace must have the <strong>Opportunities</strong> module installed, then the <strong>Contracts</strong> module (free from Marketplace — not auto-installed). Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>convert</code> as needed).</p><p>Without <strong>assign</strong>, you only see contracts assigned to you.</p><h2 id="list-table" tabindex="-1">List &amp; table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List &amp; table&quot;">​</a></h2><p>Open <strong>Contracts</strong> from the sidebar (Sales). Search by title, filter by status, opportunity, or assignee, or toggle <strong>My Contracts</strong>. The table shows the <strong>latest note</strong>; hover a truncated preview to read the full note.</p><ul><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted contract from the row menu</li><li><strong>Delete permanently</strong> requires <code>contracts.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New contract</strong></li><li>Choose the related <strong>Opportunity</strong> (required) — this auto-fills <strong>Title</strong> (when empty), <strong>Party name</strong> (from the opportunity contact or company), <strong>Value</strong>, <strong>Currency</strong>, and <strong>Assignee</strong> when the opportunity assignee is eligible (workspace owners are not listed). You can still change the fields afterward. End date must be on or after start date.</li><li>Optionally link a <strong>Quotation</strong> (only shown when the Quotations module is installed). If the opportunity has exactly one quotation, it is selected automatically; with multiple quotations, pick one or leave none</li><li>Enter a start date (required), optional end date, and optional rich-text <strong>Description</strong> and <strong>Notes</strong> (headings, lists, bold/italic/underline)</li><li>Optionally set an assignee (requires <strong>assign</strong>)</li><li>Save</li></ol><p>Edit from the row menu or the record page while the contract is still <strong>Draft</strong>. After <strong>Activate</strong>, content fields are locked; use status actions and assignment instead.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>A contract starts in <strong>Draft</strong>. Move it forward with the status action:</p><ul><li><strong>Activate</strong> (<code>draft → active</code>)</li><li><strong>Expire</strong> (<code>active → expired</code>) or <strong>Terminate</strong> (<code>draft</code>/<code>active → terminated</code>)</li></ul><p>Invalid transitions (e.g. expiring directly from Draft) are rejected with a validation error.</p><h2 id="create-invoice" tabindex="-1">Create invoice <a class="header-anchor" href="#create-invoice" aria-label="Permalink to &quot;Create invoice&quot;">​</a></h2><p>Once a contract is <strong>Active</strong> and <strong>Invoices</strong> is installed, use <strong>Create invoice</strong> from the record page or row menu (<code>contracts.convert</code>):</p><ul><li>Creates a new <strong>draft</strong> invoice. Line items come from the linked quotation when it has lines; otherwise a single line uses the contract <strong>value</strong></li><li>The invoice is linked via <code>contract_id</code> (and <code>quotation_id</code> when a quotation is linked)</li><li>You can create <strong>more than one</strong> invoice from the same contract (progress billing). The table shows a <strong>Billed</strong> badge after the first invoice</li><li>If the linked quotation already has an invoice, the confirm dialog warns you — the API still allows the extra invoice</li><li>Without Invoices installed, the action is hidden; the API returns a validation error if called directly</li></ul><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the record page or the create/edit form. The assignee receives an in-app notification when someone else assigns them.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Description</strong> and <strong>Notes</strong> — rich-text memos on the contract (shown on the overview)</li><li><strong>Notes tab</strong> — free-form comments on the contract</li><li><strong>Activity</strong> — timeline of create, update, assignment, status change, invoice creation, note, and delete/restore events</li></ul>',21)])])}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
